import { useEffect, useRef, useState } from "react";
import HeroCard from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 26 },
  { id: 2,  label: "DL Verification", angle: 147.3, rotate: 9,   z: 27 },
  { id: 3,  label: "KYC Check",       angle: 114.5, rotate: -6,  z: 28 },
  { id: 4,  label: "Aadhaar",         angle: 81.8,  rotate: 5,   z: 29 },
  { id: 5,  label: "Face Match",      angle: 49.1,  rotate: -9,  z: 29 },
  { id: 6,  label: "PAN Card",        angle: 16.4,  rotate: 12,  z: 28 },
  { id: 7,  label: "Fraud Alert",     angle: 343.6, rotate: -5,  z: 27 },
  { id: 8,  label: "Bank Verify",     angle: 310.9, rotate: 11,  z: 28 },
  { id: 9,  label: "Credit Score",    angle: 278.2, rotate: -5,  z: 29 },
  { id: 10, label: "Background Chk",  angle: 245.5, rotate: -10, z: 28 },
  { id: 11, label: "Employment",      angle: 212.7, rotate: 9,   z: 27 },
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw]             = useState(0);
  const sectionRef              = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(
        -el.getBoundingClientRect().top / (el.offsetHeight * 0.62),
        0, 1
      );
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  /*
   * Responsive breakpoints
   * xs: < 400px  (small phones)
   * sm: 400–599px
   * md: 600–1023px (tablets)
   * lg: >= 1024px (desktop — unchanged)
   */
  const isXs = vw > 0 && vw < 400;
  const isSm = vw >= 400 && vw < 600;
  const isMd = vw >= 600 && vw < 1024;
  const isLg = vw >= 1024;
  const isMobile = vw > 0 && vw < 600;

  /*
   * Title font size:
   *   xs: 32px | sm: 40px | md: 54px | lg: 90px (unchanged)
   */
  const titleFontSize = isLg ? "90px"
    : isMd ? "54px"
    : isSm ? "40px"
    : isXs ? "32px"
    : "90px"; // SSR fallback

  /*
   * Subtitle font size:
   *   xs: 16px | sm: 19px | md: 26px | lg: 52px (unchanged)
   */
  const subtitleFontSize = isLg ? "52px"
    : isMd ? "26px"
    : isSm ? "19px"
    : isXs ? "16px"
    : "52px";

  /*
   * Subtitle top position:
   * On mobile the cards cluster tightly in the center so we push
   * the subtitle lower to avoid overlap, then let it be clipped by
   * the viewport — the cards fade out on scroll anyway.
   *   xs/sm: 68% | md: 65% | lg: 62% (unchanged)
   */
  const subtitleTop = isLg ? "62%"
    : isMd ? "65%"
    : "70%";

  /*
   * Gentle text scale: 0.92 → 1.0 as progress goes 0 → 0.75
   * Subtle opacity lift: 0.75 → 1.0 over the same window
   */
  const textEnterT  = ease(clamp(progress / 0.75, 0, 1));
  const textScale   = lerp(0.92, 1.0, textEnterT);
  const textOpacity = lerp(0.75, 1.0, textEnterT);

  /*
   * On mobile we reduce subtitle top margin so it sits closer to title
   */
  const subtitleMarginTop = isLg ? "30px" : isMd ? "18px" : "10px";

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* ── TITLE ── */}
        <div
          style={{
            position: "absolute",
            /*
             * On mobile, shift title higher so it clears the card cluster.
             * Desktop: centered (top 50% via flex). Mobile: absolute top.
             */
            top: isMobile ? "12%" : isMd ? "14%" : undefined,
            zIndex: 15,
            textAlign: "center",
            width: "92vw",
            maxWidth: "1300px",
            opacity: textOpacity,
            transform: `scale(${textScale})`,
            willChange: "transform, opacity",
            padding: isMobile ? "0 16px" : "0",
          }}
        >
          <h1
            style={{
              fontFamily: "Inter",
              fontSize: titleFontSize,
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
              whiteSpace: "normal",
              overflowWrap: "break-word",
              wordBreak: "break-word",
              letterSpacing: "-0.02em",
            }}
          >
            Deception from
            <br />
            Click to the Doorstep
          </h1>
        </div>

        {/* ── SUBTITLE ── */}
        <div
          style={{
            position: "absolute",
            top: subtitleTop,
            left: "50%",
            transform: `translateX(-50%) scale(${textScale})`,
            width: isMobile ? "88vw" : "92vw",
            maxWidth: "1300px",
            zIndex: 16,
            textAlign: "center",
            pointerEvents: "none",
            opacity: textOpacity,
            willChange: "transform, opacity",
            padding: isMobile ? "0 8px" : "0",
          }}
        >
          <p
            style={{
              fontSize: subtitleFontSize,
              fontWeight: 500,
              color: "white",
              margin: 0,
              lineHeight: 1.3,
              opacity: 0.88,
              marginTop: subtitleMarginTop,
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>
        </div>

        {/* ── Cards layer ── */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 25,
          }}
        >
          {CARDS.map(c => (
            <HeroCard key={c.id} card={c} progress={progress} vw={vw} />
          ))}
        </div>
      </div>
    </div>
  );
}
